(function(){"use strict";var header=document.querySelector('.site-header');function onScroll(){if(!header)return;if(window.scrollY>40){header.classList.add('solid');}else{header.classList.remove('solid');}}window.addEventListener('scroll',onScroll,{passive:true});onScroll();var toggle=document.querySelector('.nav-toggle');var mobileMenu=document.querySelector('.mobile-menu');if(toggle&&mobileMenu){toggle.addEventListener('click',function(){mobileMenu.classList.toggle('open');document.body.classList.toggle('menu-open');toggle.setAttribute('aria-expanded',mobileMenu.classList.contains('open'));});mobileMenu.querySelectorAll('a').forEach(function(a){a.addEventListener('click',function(){mobileMenu.classList.remove('open');document.body.classList.remove('menu-open');});});}var fc=document.querySelector('.floating-contact');if(fc){var fcToggle=fc.querySelector('.fc-toggle');fcToggle.addEventListener('click',function(){fc.classList.toggle('open');fcToggle.setAttribute('aria-expanded',fc.classList.contains('open'));});document.addEventListener('click',function(e){if(!fc.contains(e.target)){fc.classList.remove('open');}});}document.querySelectorAll('.faq-item').forEach(function(item){var q=item.querySelector('.faq-q');var a=item.querySelector('.faq-a');if(!q||!a)return;q.addEventListener('click',function(){var isOpen=item.classList.contains('open');item.parentElement.querySelectorAll('.faq-item').forEach(function(i){i.classList.remove('open');i.querySelector('.faq-a').style.maxHeight=null;});if(!isOpen){item.classList.add('open');a.style.maxHeight=a.scrollHeight+'px';}});});document.querySelectorAll('.tabs').forEach(function(tabGroup){var buttons=tabGroup.querySelectorAll('button');var targetSel=tabGroup.getAttribute('data-target');var panels=targetSel?document.querySelectorAll(targetSel+'[data-tab-panel]'):[];buttons.forEach(function(btn){btn.addEventListener('click',function(){buttons.forEach(function(b){b.classList.remove('active');});btn.classList.add('active');var val=btn.getAttribute('data-tab');panels.forEach(function(p){p.style.display=(p.getAttribute('data-tab-panel')===val||val==='all')?'':'none';});});});});var filterBar=document.querySelector('.gallery-filters');if(filterBar){var items=document.querySelectorAll('.gallery-grid .g-item');filterBar.querySelectorAll('button').forEach(function(btn){btn.addEventListener('click',function(){filterBar.querySelectorAll('button').forEach(function(b){b.classList.remove('active');});btn.classList.add('active');var f=btn.getAttribute('data-filter');items.forEach(function(it){var cats=(it.getAttribute('data-cat')||'').split(' ');it.style.display=(f==='all'||cats.indexOf(f)!==-1)?'':'none';});});});}var lightbox=document.querySelector('.lightbox');if(lightbox){var lbImg=lightbox.querySelector('img');var lbCap=lightbox.querySelector('.lb-cap');var gallery=Array.prototype.slice.call(document.querySelectorAll('[data-lightbox]'));var current=0;function openAt(i){if(!gallery.length)return;current=(i+gallery.length)% gallery.length;var el=gallery[current];var full=el.getAttribute('data-full')||el.querySelector('img').src;lbImg.src=full;lbImg.alt=el.getAttribute('data-alt')||'';lbCap.textContent=el.getAttribute('data-caption')||'';lightbox.classList.add('open');document.body.classList.add('menu-open');}gallery.forEach(function(el,i){el.addEventListener('click',function(){openAt(i);});el.setAttribute('tabindex','0');el.addEventListener('keypress',function(e){if(e.key==='Enter')openAt(i);});});var closeBtn=lightbox.querySelector('.lb-close');var prevBtn=lightbox.querySelector('.lb-prev');var nextBtn=lightbox.querySelector('.lb-next');function close(){lightbox.classList.remove('open');document.body.classList.remove('menu-open');}if(closeBtn)closeBtn.addEventListener('click',close);if(prevBtn)prevBtn.addEventListener('click',function(){openAt(current-1);});if(nextBtn)nextBtn.addEventListener('click',function(){openAt(current+1);});lightbox.addEventListener('click',function(e){if(e.target===lightbox)close();});document.addEventListener('keydown',function(e){if(!lightbox.classList.contains('open'))return;if(e.key==='Escape')close();if(e.key==='ArrowLeft')openAt(current-1);if(e.key==='ArrowRight')openAt(current+1);});}document.querySelectorAll('form[data-netlify-form]').forEach(function(form){form.addEventListener('submit',function(e){e.preventDefault();var data=new FormData(form);fetch('/',{method:'POST',body:data}).then(function(){form.style.display='none';var success=form.parentElement.querySelector('.form-success');if(success)success.classList.add('show');}).catch(function(){form.removeEventListener('submit',arguments.callee);form.submit();});});});var revealEls=document.querySelectorAll('.reveal');if('IntersectionObserver' in window&&revealEls.length){var io=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('in-view');io.unobserve(entry.target);}});},{threshold:0.12});revealEls.forEach(function(el){io.observe(el);});}else{revealEls.forEach(function(el){el.classList.add('in-view');});}})();